          "q_en": "What did Momotaro set out to defeat?",
          "q_te": "మోమోతారో దేనిని ఓడించడానికి బయలుదేరాడు?",
          "q_hi": "मोमोतारो किसे हराने के लिए निकला?",
          "q_ta": "மோமோடாரோ எதை வெல்லப் புறப்பட்டான்?",
