          "q_en": "Why did Gon feel deep remorse?",
          "q_te": "గోన్ ఎందుకు తీవ్రంగా పశ్చాత్తాపపడింది?",
          "q_hi": "गोन को गहरा पछतावा क्यों हुआ?",
          "q_ta": "கோன் ஏன் மிகவும் வருந்தியது?",
