          "q_en": "As a teacher of what subject was the protagonist sent to the middle school in Shikoku?",
          "q_te": "కథానాయకుడు ఏ సబ్జెక్ట్ టీచర్‌గా ఉద్యోగానికి వెళ్ళాడు?",
