          "q_kn": "ಗಡಿಪಾರಾಗುತ್ತಿದ್ದರೂ ಕಿಸುಕೆ ಏಕೆ ಪ್ರಶಾಂತವಾಗಿದ್ದನು?",
          "q_ml": "നാടുകടത്തപ്പെടുമ്പോഴും കിസുകെ സന്തോഷവാനായിരുന്നത് എന്തുകൊണ്ടാണ്?",
