      "passage_ta": "ஆரோக்கியம் என்ற கட்டாயம்: எதை உண்பது என்ற கணக்கீடுகள் உணவருந்தும் மேசையை ஊட்டச்சத்து ஆய்வகமாக மாற்றிவிட்டன. உணவின் உண்மையான சுவையும், பகிர்ந்தளிக்கும் மகிழ்ச்சியும் மறைந்துபோவது முரண்பாடானது.",
