      "passage_kn": "ಆರೋಗ್ಯದ ಬಗೆಗಿನ ಅತಿಯಾದ ಆತಂಕ: ಪೌಷ್ಟಿಕಾಂಶಗಳ ಲೆಕ್ಕಾಚಾರದಿಂದ ಊಟದ ಮೇಜು ಪ್ರಯೋಗಾಲಯದಂತಾಗಿದೆ. ಊಟದ ರುಚಿ ಮತ್ತು ಜೊತೆಯಾಗಿ ತಿನ್ನುವ ಆನಂದವೇ ಮರೆಯಾಗುತ್ತಿರುವುದು ವಿಪರ್ಯಾಸ.",
