          "q_kn": "ನಿಜವಾಗಿ ಅರ್ಥಮಾಡಿಕೊಳ್ಳುವುದು ಎಂದರೇನು?",
          "q_ml": "യഥാർത്ഥത്തിൽ മനസ്സിലാക്കുക എന്നാൽ എന്താണ് അർത്ഥമാക്കുന്നത്?"
