          "q_es": "¿Qué actitud valora más el autor?",
          "q_kn": "ಲೇಖಕರು ಯಾವ ಮನೋಭಾವವನ್ನು ಅತ್ಯಂತ ಮೌಲ್ಯಯುತವೆಂದು ಕಾಣುತ್ತಾರೆ?",
          "q_ml": "ഏത് മനോഭാവത്തിനാണ് ലേഖകൻ കൂടുതൽ വില കൽപ്പിക്കുന്നത്?"
