          "q_kn": "ಮೆಲೋಸ್ ಬದಲಿಗೆ ಒತ್ತೆಯಾಳಾಗಿದ್ದ ಮಿತ್ರನ ಹೆಸರೇನು?",
          "q_ml": "മെലോസിന് പകരം തടവുകാരനായ സുഹൃത്തിന്റെ പേരെന്താണ്?",
