          "q_kn": "ಗುರುಗಳು ಪ್ರತಿ ತಿಂಗಳು ಯಾರ ಸಮಾಧಿಗೆ ಹೋಗುತ್ತಿದ್ದರು?",
          "q_ml": "സെൻസെ എല്ലാ മാസവും ആരുടെ കല്ലറയിലാണ് പോയിരുന്നത്?",
