          "q_en": "Who is the literary master of the Meiji and Taisho eras who authored this novel?",
          "q_te": "ఈ నవల రచయిత అయిన ప్రసిద్ధ జపనీస్ రచయిత ఎవరు?",
          "q_hi": "इस प्रसिद्ध उपन्यास के रचयिता कौन हैं?",
